/// `G/internal/api/common/error_test.go` `TestOpenAIErrorType`.
#[test]
fn openai_error_type_table() {
    let cases = [
        (
            "invalid_argument: model does not support image",
            "invalid_request_error",
        ),
        (
            "resource_exhausted: rate limit exceeded",
            "rate_limit_error",
        ),
        ("permission_denied: not allowed", "invalid_request_error"),
        ("not_found: model missing", "not_found_error"),
        ("unavailable: upstream offline", "server_error"),
        ("some unknown error", "server_error"),
        // Upstream internal faults stuffed into fixable codes stay
        // server_error — the blame is upstream's.
        (
            "invalid_argument: an internal error occurred (trace ID: abc)",
            "server_error",
        ),
    ];
    for (message, want) in cases {
        let failure = devin2api::domain::classify_text(message);
        assert_eq!(
            openai_error_type(&failure),
            want,
            "OpenAIErrorType({message:?})"
        );
    }
}

/// `G/internal/api/common/error_test.go` `TestAnthropicErrorType`.
#[test]
fn anthropic_error_type_table() {
    let cases = [
        ("invalid_argument: bad request", "invalid_request_error"),
        (
            "resource_exhausted: rate limit exceeded",
            "rate_limit_error",
        ),
        ("permission_denied: not allowed", "invalid_request_error"),
        ("not_found: model missing", "not_found_error"),
        ("unavailable: upstream offline", "api_error"),
        ("some unknown error", "api_error"),
        (
            "permission_denied: an internal error occurred (trace ID: abc)",
            "api_error",
        ),
    ];
    for (message, want) in cases {
        let failure = devin2api::domain::classify_text(message);
        assert_eq!(
            anthropic_error_type(&failure),
            want,
            "AnthropicErrorType({message:?})"
        );
    }
}

/// `G/internal/api/common/error_test.go` `TestHTTPStatus`.
#[test]
fn http_status_table() {
    let cases = [
        ("permission_denied: blocked by content policy", 400),
        (
            "invalid_argument: The prompt is too long for this model",
            413,
        ),
        ("invalid_argument: internal error", 400),
        ("unauthenticated: bad token", 401),
        ("not_found: model missing", 404),
        ("resource_exhausted: quota", 429),
        ("unavailable: TLS handshake timeout", 502),
        ("stream disconnected", 502),
        (
            "invalid_argument: an internal error occurred (trace ID: abc)",
            502,
        ),
        (
            "invalid_argument: protocol error: incomplete envelope: read: connection reset by peer",
            502,
        ),
    ];
    for (message, want) in cases {
        let failure = devin2api::domain::classify_text(message);
        assert_eq!(http_status(&failure), want, "HTTPStatus({message:?})");
    }
}

/// `G/internal/api/common/error_test.go` `TestErrorCode`.
#[test]
fn error_code_table() {
    let failure =
        devin2api::domain::classify_text("invalid_argument: The prompt is too long for this model");
    assert_eq!(error_code(&failure), json!("context_length_exceeded"));
    let failure = devin2api::domain::classify_text("permission_denied: blocked");
    assert_eq!(error_code(&failure), Value::Null);
}

