/// `G/internal/api/`openai`/responses/response_test.go`
/// `TestStreamEncoderEncodesReasoningAndToolItems`.
#[test]
fn stream_encoder_encodes_reasoning_and_tool_items() {
    let (_case, expected, actual) = assert_case_parity("responses_stream_reasoning_and_tool_items");
    // Go asserts resp_/rs_/fc_ prefixes on generated ids; canonicalization
    // already proved cross-side equality, so check the Rust side's shape.
    let created = sse_data(&actual, 0);
    assert!(
        created["response"]["id"]
            .as_str()
            .is_some_and(|id| id.starts_with("resp_")),
        "response id prefix"
    );
    let reasoning_added = sse_data(&actual, 2);
    let reasoning_id = reasoning_added["item"]["id"].as_str().unwrap();
    assert!(reasoning_id.starts_with("rs_"), "reasoning id prefix");
    assert_eq!(sse_data(&actual, 4)["item_id"], json!(reasoning_id));
    let tool_added = sse_data(&actual, 8);
    let tool_item_id = tool_added["item"]["id"].as_str().unwrap();
    assert!(tool_item_id.starts_with("fc_") && tool_item_id != "call-1");
    assert_eq!(tool_added["item"]["call_id"], json!("call-1"));
    assert_eq!(sse_data(&actual, 9)["item_id"], json!(tool_item_id));
    let completed = sse_data(&actual, actual.sse.len() - 1);
    assert_eq!(completed["response"]["id"], created["response"]["id"]);
    let output = completed["response"]["output"].as_array().unwrap();
    assert_eq!(output.len(), 2);
    assert_eq!(output[0]["type"], json!("reasoning"));
    assert_eq!(output[1]["type"], json!("function_call"));
    assert_eq!(output[1]["call_id"], json!("call-1"));
    // sequence_number is a dense 0..n counter across the whole stream.
    for (index, event) in actual.sse.iter().enumerate() {
        let data: Value = serde_json::from_slice(&event.data).unwrap();
        assert_eq!(data["sequence_number"], json!(index), "event[{index}]");
    }
    assert_eq!(expected.sse.len(), actual.sse.len());
}

/// `G/internal/api/`openai`/responses/response_test.go`
/// `TestStreamEncoderEncodesFinalTextMessage`.
#[test]
fn stream_encoder_encodes_final_text_message() {
    let (_case, _expected, actual) = assert_case_parity("responses_stream_final_text_message");
    let item_added = sse_data(&actual, 2);
    let message_id = item_added["item"]["id"].as_str().unwrap();
    assert!(message_id.starts_with("msg_"), "message id prefix");
    let part_added = sse_data(&actual, 3);
    assert_eq!(part_added["item_id"], json!(message_id));
    assert_eq!(part_added["content_index"], json!(0));
    let completed = sse_data(&actual, actual.sse.len() - 1);
    let message = &completed["response"]["output"][0];
    assert_eq!(message["type"], json!("message"));
    assert_eq!(message["content"][0]["text"], json!("final answer"));
}

/// `G/internal/api/`openai`/responses/response_test.go`
/// `TestStreamEncoderHoldsReasoningForLateSignature`.
#[test]
fn stream_encoder_holds_reasoning_for_late_signature() {
    let (_case, _expected, actual) = assert_case_parity("responses_stream_late_signature");
    let reasoning_done = sse_data(&actual, 11);
    assert_eq!(reasoning_done["item"]["encrypted_content"], json!("sig"));
    let completed = sse_data(&actual, actual.sse.len() - 1);
    assert_eq!(
        completed["response"]["output"][0]["encrypted_content"],
        json!("sig")
    );
}

/// `G/internal/api/`openai`/responses/response_test.go`
