/// `G/internal/api/`openai`/responses/response_test.go`
/// `TestStreamEncoderRejectsUnknownEvent`. Go's `Type` is a free string; the
/// Rust `ResponseEventType` enum is closed, so an unknown kind is
/// unrepresentable — the fixture asserts the Go side rejected it.
#[test]
fn stream_encoder_rejects_unknown_event() {
    let (_case, expected, actual) = assert_case_parity("responses_stream_rejects_unknown_event");
    assert!(expected.encode_error.is_some());
    assert!(actual.unrepresentable);
    // The encoder still refuses events that fail validation.
    let mut encoder = dispatch::ResponsesProtocol.new_stream_encoder("gpt-test", false);
    let invalid = ResponseEvent {
        kind: ResponseEventType::TextDelta,
        content_index: 0,
        ..ResponseEvent::default()
    };
    assert!(encoder.encode(&invalid).is_err());
}

