/// `G/internal/api/`openai`/chat/response_test.go` `TestStreamEncoderEmitsError`.
#[test]
fn stream_encoder_emits_error() {
    let (_case, _expected, actual) = assert_case_parity("chat_stream_error");
    assert_eq!(actual.sse.len(), 2);
    assert_eq!(actual.sse[0].name, "");
    assert_eq!(actual.sse[1].name, common::SSE_DONE);
    let data = sse_data(&actual, 0);
    assert_eq!(data["object"], json!("chat.completion.chunk"));
    assert_eq!(data["choices"].as_array().unwrap().len(), 0);
    assert_eq!(
        data["error"]["message"],
        json!("resource_exhausted: rate limit exceeded")
    );
    assert_eq!(data["error"]["type"], json!("rate_limit_error"));

    // Encoding after the error must fail — the stream is done.
    let mut encoder = dispatch::ChatProtocol.new_stream_encoder("gpt-test", false);
    let failed = AssistantMessage {
        provider: "devin".to_string(),
        stop_reason: Some(StopReason::Error),
        error_message: "resource_exhausted: rate limit exceeded".to_string(),
        ..AssistantMessage::default()
    };
    let event = ResponseEvent {
        kind: ResponseEventType::Error,
        reason: Some(StopReason::Error),
        error: Some(failed),
        ..ResponseEvent::default()
    };
    assert!(encoder.encode(&event).is_ok());
    assert!(
        encoder.encode(&event).is_err(),
        "encode after error must fail"
    );
}

